def transform(grid):
    if not grid or not grid[0]:
        return grid

    rows, cols = len(grid), len(grid[0])

    from collections import Counter
    counts = Counter()
    for r in range(rows):
        for c in range(cols):
            counts[grid[r][c]] += 1

    # Get most frequent as background
    if len(counts) > 0:
        background = max(counts, key=counts.get)
    else:
        background = 0

    # The pattern is always the rightmost 10 columns
    pattern_width = min(10, cols)

    output = []
    for r in range(rows):
        new_row = []

        # Left section: reversed pattern
        pattern = []
        for c in range(pattern_width):
            pattern.append(grid[r][cols - 1 - c])
        for i in range(pattern_width):
            new_row.append(pattern[pattern_width - 1 - i])

        # Middle: background columns (if any)
        if cols > pattern_width * 2:
            local_index = 1 + (cols - 2 * pattern_width)
            for l in range(local_index):
                new_row.append(background)

        # Right: original pattern
        for c in range(pattern_width):
            new_row.append(grid[r][cols - 1 - c])

        output.append(new_row)

    return output
